/**
 * 游戏流辅助类
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        let total = SlotsFacade.dm.GetTotalFree();
        let rest = SlotsFacade.dm.GetFreeTime();
        if(rest > 0){
            SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal)

            SlotsFacade.topCmp.SetBackLobby(false);
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            SlotsFacade.mainPanel.showBg(true);
            SlotsFacade.slots.setBorderVisible(false);
            SlotsFacade.slots.showSlotsState(true);
            SlotsFacade.freeGame.reconnect();
            SlotsFacade.slots.CanDoNextRound();
        }
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        if(!SlotsFacade.dm.isFistTriggerFree()) {
            SlotsFacade.slots.resetReelBg();
        }
        await SlotsFacade.freeGame.processUnlock();
        await SlotsFacade.slots.changeWildMultiple();
        await this.jpGame();

        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin();
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal, SlotsFacade.dm.GetTotalFree()==0, res);
        });

        // 控制按钮
        if(SlotsFacade.dm.isTriggerFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            await SlotsFacade.slots.playScatter(SlotsFacade.dm.getScatterIndexs());
            if (SlotsFacade.dm.isFistTriggerFree()) {
                SlotsFacade.slots.Backup();
            }
            await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.triggerFreeCnt(), SlotsFacade.dm.isFistTriggerFree());
            if(SlotsFacade.dm.isFistTriggerFree()) {
                SlotsFacade.mainPanel.showSceneTransition();
                await SlotsFacade.delayTime(2);
                await this.enterFreeGame();
            }
            await SlotsFacade.delayTime(1);
            // SlotsFacade.slots.CanDoNextRound()
        }else if(cc.vv.gameData.hasFree()) {
        }else if(cc.vv.gameData.isLastEndFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            let freeWinCoin = SlotsFacade.dm.getFreeWinCoin();
            await SlotsFacade.popup.showWinGold(freeWinCoin);
            SlotsFacade.mainPanel.showSceneTransition();
            await SlotsFacade.delayTime(1);
            SlotsFacade.slots.Resume();
            this.enterNormalGame();
            await SlotsFacade.delayTime(2.8);
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(freeWinCoin, freeWinCoin, true, res);
            });
        }
        SlotsFacade.slots.CanDoNextRound()
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame() {
        SlotsFacade.slots.resetReelBg();
        SlotsFacade.mainPanel.showBg(true);
        SlotsFacade.soundMgr.playFreeBgm();
        SlotsFacade.freeGame.show();
        SlotsFacade.slots.showSlotsState(true, true, 1.5, 0.5);
        SlotsFacade.slots.setBorderVisible(false);
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        await SlotsFacade.delayTime(2.5);
    },

    /**
     * 进入普通游戏
     */
    enterNormalGame() {
        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.slots.setBorderVisible(true);
        SlotsFacade.mainPanel.showBg(false);
        SlotsFacade.freeGame.hide();
        SlotsFacade.slots.showSlotsState(false);
        SlotsFacade.slots.setBorderVisible(true);
        SlotsFacade.slots.clearFreeSymbols();
        Global.SlotsSoundMgr.stopBgm();
        SlotsFacade.soundMgr.playBgm();
    },

    /**
     * jp 游戏
     */
    async jpGame() {
        let jackpotInfo = SlotsFacade.dm.getSpinData().jackpotInfo;
        if(!jackpotInfo) {
            return;
        }
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        // 播放jackport动画逻辑
        let sum = 0;
        for(let i=0; i<jackpotInfo.jackpotIds.length; i++) {
            let jpType = jackpotInfo.jackpotIds[i];
            let winCoin = jackpotInfo.coins[i];
            let jpIdxs = jackpotInfo.idxs[i];
            let isBig = false;
            let idx = jpIdxs[0];
            if(jpIdxs.length == 2) {
                isBig = true;
                idx = jpIdxs[1];
            }
            let symbol = SlotsFacade.slots.GetSymbolByIdx(idx);
            await symbol.playJp(jpType, isBig);
            await SlotsFacade.popup.showJpWinGold(jpType, winCoin);
            sum += winCoin;
            SlotsFacade.bottomCmp.SetWin(sum);
        }
        // jp转变到wild动画逻辑
        let resultCards = SlotsFacade.dm.getSpinData().resultCards;
        for(let i=0; i<jackpotInfo.jackpotIds.length; i++) {
            let jpIdxs = jackpotInfo.idxs[i];
            let cards = [];
            if(jpIdxs.length == 2) {
                cards.push(resultCards[jpIdxs[0]-1]);
                cards.push(resultCards[jpIdxs[0]-1] + 2000);
            }else {
                // 不在最后一排必然是wild的下半部分
                let idx = jpIdxs[0];
                if(idx + 5 > 40) {
                    cards.push(resultCards[idx-1]);
                }else {
                    cards.push(resultCards[idx-1] + 2000);
                }
            }
            for(let j=0; j<jpIdxs.length; j++) {
                let symbol = SlotsFacade.slots.GetSymbolByIdx(jpIdxs[j]);
                symbol.ShowById(cards[j]);
                if(j == jpIdxs.length-1) {
                    await symbol.jpToWild(jpIdxs.length == 2);
                }
            }
        }
        await SlotsFacade.delayTime(0.5);
    },
})