/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        afterProcessingCards:null, // 处理过后的symbols
    },

    SetSubGameData:function(data){
        this._subGame = data
    },

    GetSubGameData:function(){
        return this._subGame
    },

    /**
     * 处理卷轴结果替换相应id
     * @param {*} cards 
     */
    processResultCards(cards) {
        let result = cards.concat();
        let row = 8;
        let col = 5;
        let Cfg = this.getGameCfg();
        let wildIdMap = {
            "1":2001,
            "101":2101,
            "102":2102
        };
        for(let i=0; i<result.length; i++) {
            let c = result[i];
            if(!Cfg.isWild(c)) {
                continue;
            }
            let crrRow = Math.floor(i/col); // 当前所处的行 0-7
            let upperIsScatter = false; // 这张牌上面是否有scatter
            let downIsScatter = false;  // 这张牌下面是否有scatter
            if(crrRow == 0) { // 如果在第一行上面必然没有scatter
                upperIsScatter = false;
            }else {  
                upperIsScatter = Cfg.isWild(result[i-col]) && wildIdMap[result[i-col]];
            }
            if(crrRow == row-1) {
                downIsScatter = false;// 如果在最后一行,下面必然没有scatter
            }else {
                downIsScatter = Cfg.isWild(result[i+col]);
            }

            if(crrRow == 0) {
                if(!downIsScatter) {
                    result[i] = wildIdMap[c];
                }
            }else if(crrRow == 4) {
                if(upperIsScatter) {
                    result[i] = wildIdMap[c];
                }
            }else {
                if(upperIsScatter) {
                    result[i] = wildIdMap[c];
                }
            }
        }

        // jack port 处理 id替换成jackport id
        let jackpotInfo = this._gameInfo.jackpotInfo;
        if(jackpotInfo) {
            for(let i=0; i<jackpotInfo.jackpotIds.length; i++) {
                let jpIdxs = jackpotInfo.idxs[i];
                if(jpIdxs.length == 1) {
                    result[jpIdxs[0]-1] = 2201;
                }else if(jpIdxs.length == 2) {
                    result[jpIdxs[0]-1] = 2301;
                    result[jpIdxs[1]-1] = 2401;
                }
            }
        }
        return result;
    },

    /**
     * 获取多倍数 wild 对
     */
    getMultipleWildIdxPairs() {
        let ret = [];
        let cards = this.afterProcessingCards.concat();
        for(let i=0; i<cards.length; i++) {
            let idx = i+1;
            if(!this.isUnlockIdx(idx, true)) {
                continue;
            }
            let info = [];
            let element = cards[i];
            if(this.getGameCfg().isMultipleWild(element)) {
                if(element < 2000) { // wild的上半部分
                    info.push(idx);
                    if(idx+5<=40 && cards[i+5] == element+2000) {// 下半部分
                        info.push(idx+5);
                        cards[i+5] = 0;
                    }
                }else {// wild的下半部分
                    info.push(idx);
                }
                ret.push(info);
            }
        }
        return ret;
    },

    getSpinData() {
        return this._gameInfo;
    },

    ////////////////////////免费相关///////////////////////
    /**
     * 免费游戏重免费卷轴相关数据
     */
    getJungleKing() {
        if(this._gameInfo) {
            return this._gameInfo.jungleKing;
        }
        return this._deskInfo.jungleKing;
    },
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return  this.GetTotalFree() > 0 && this.GetFreeTime() !== this.GetTotalFree() && this.GetFreeTime() > 0;
    },

    inFree() {
        return  this.GetTotalFree() > 0 && this.GetFreeTime() !== this.GetTotalFree();
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let freeResult = this._gameInfo.freeResult;
        if(freeResult && freeResult.triFreeCnt  && freeResult.freeInfo && freeResult.freeInfo.freeCnt) {
           return freeResult.freeInfo.freeCnt;
        }
        return 0;
    },
    
    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.GetTotalFree() > 0 && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() === 0 && this.GetTotalFree() > 0;
    },

    /**
     * 免费游戏赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this._gameInfo.freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    /**
     * 检测坐标是否解锁
     * @param {*} idx 
     * @param {*} isAfterUnlock 是否计算解锁后的数据
     */
    isUnlockIdx(idx, isAfterUnlock) {
        if(idx > 20) {
            return true;
        }
        if(!this.hasFree()) {
            return false;
        }
        if(this.isFistTriggerFree()) {
            return false;
        }
        isAfterUnlock = isAfterUnlock || false;
        let unlockIdx = [];
        let jungleKing = this.getJungleKing();
        let unlockCnt = jungleKing.total;
        if(!isAfterUnlock) {
            unlockCnt -= jungleKing.idxs.length;
        }
        if(unlockCnt >= 3) {
            unlockIdx.push(17, 18, 19);
        }
        if(unlockCnt >= 7) {
            unlockIdx.push(12, 13, 14);
        }
        if(unlockCnt >= 11) {
            unlockIdx.push(7, 8, 9);
        }
        if(unlockCnt >= 15) {
            unlockIdx.push(2, 3, 4);
        }
        if(unlockIdx.includes(idx)) {
            return true;
        }
        return false;
    }
});
