cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
       
    },

    Init:function () {
        this._super();

        // this.node.parent.parent.getComponent("LMSlots_Puzzle").setCallback(async (freeInfo, chipGame)=>{
        //     // 进入免费的逻辑
        //     cc.vv.gameData.SetTotalFree(freeInfo.freeCnt);
        //     cc.vv.gameData.SetFreeTime(freeInfo.freeCnt);
        //
        //     await SlotsFacade.popup.showWinFreeCnt(cc.vv.gameData.GetTotalFree(), true);
        //     SlotsFacade.mainPanel.showSceneTransition();
        //     await SlotsFacade.delayTime(2);
        //     await SlotsFacade.flowCtrl.enterFreeGame();
        //     await SlotsFacade.delayTime(1);
        //     SlotsFacade.slots.CanDoNextRound()
        // });
    },

    //重写
    StartMove:function(){
        this._super();
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            SlotsFacade.soundMgr.playBgm();
        }
        this.resetReelBg();
    },

    SetReelStateInfo:function(cards){
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            if(!SlotsFacade.dm.isUnlockIdx(i+1, false)) {
                continue;
            }
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }
        let needCheekAddSpeed = !SlotsFacade.dm.hasFree() || SlotsFacade.dm.isFistTriggerFree();
        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info); 
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);  
            let haveCount = 0
    
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (needCheekAddSpeed && haveCount >= triggerCount-1 && stateInfo.counts[i] > 0) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    /**
     * @override
     * @param {*} msg 
     */
    onMsgSpine:function(msg){
        this._gameInfo = msg
        let cards = SlotsFacade.dm.processResultCards(msg.resultCards);
        SlotsFacade.dm.afterProcessingCards = cards.concat();
        this.SetSlotsResult(cards)
        this.SetReelStateInfo(cards)
    },

    //重写：显示bonus中奖
    OnSpinEnd:function(){
        SlotsFacade.flowCtrl.spinEnd();
    },

    /**
     * 检测列是否有scatter图标
     */
    hasScatter(colIdx) {
        let scatterId = cc.vv.gameData.getGameCfg().scatterId;
        let sysResult = this._reels[colIdx]._symbols;
        for(let j = 0; j < 4; j++){
            if(sysResult[j].GetShowId() == scatterId){
                return true;
            }
        }
        return false;
    },

    /**
     * @override
     */
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
        
    },

    showSlotsState(isFree, ani, time, delayTime) {
        for (let i = 1; i < 4; i++){
            let reel = this._reels[i];
            if(isFree) {
                if(ani) {
                    cc.tween(reel.GetResizeHeightObjs()[0])
                        .delay(delayTime)
                        .to(time, {height:760})
                        .start()
                    cc.tween(reel.GetResizeHeightObjs()[1])
                        .delay(delayTime)
                        .to(time, {height:760})
                        .start()
                }else {
                    reel.GetResizeHeightObjs()[0].height = 760;
                    reel.GetResizeHeightObjs()[1].height = 760;
                }
            }else {
                reel.GetResizeHeightObjs()[0].height = 380;
                reel.GetResizeHeightObjs()[1].height = 380;
            }
        }
    },

    /**
     * 显示边框
     * @param {*} boo 
     */
    setBorderVisible(boo) {
        let frame = this.node.getChildByName("reels_frame");
        frame.active = boo;
    },

    /**
     * 播放scatter 中奖动画
     */
    async playScatter(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playWinAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 变化wild图标的倍数
     */
    async changeWildMultiple() {
        let wildPair = SlotsFacade.dm.getMultipleWildIdxPairs();
        wildPair.forEach(element => {
            let symbol = this.GetSymbolByIdx(element[element.length-1]);
            symbol.canPlayWinMultiple = true;
            symbol.showMultiple(true, 1, element.length==1);
        });
        if(wildPair && wildPair.length) {
            SlotsFacade.soundMgr.playEffect("wild");
            await SlotsFacade.delayTime(0.5);
        }
    },
    
    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },

    /**
     * 重置reel背景
     */
    resetReelBg() {
        this._reels.forEach(element => {
            element.changeReelBg(false);
        });
    },

    clearFreeSymbols() {
        for(let i=0; i<this._reels.length; i++) {
            let symbols = this._reels[i]._symbols;
            for(let j=0; j<symbols.length; j++) {
                if(j > 3) {
                    symbols[j].StartMove();
                }
            }
        }
    }
});
