/**
 * 弹窗管理器
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node
    },

    onLoad() {
        this.bg = this.node.getChildByName("bg");
    },

    showBg(boo) {
        this.bg.active = boo;
    },

    /**
     * 显示赢取金币
     * @param {number} goldNumb 
     */
    async showWinGold(goldNumb) {
        SlotsFacade.soundMgr.playEffect("free_dialog_collect_show");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_coin");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent("LabelRollCmp").startRoll(0, goldNumb);
        let okBtn = panel.getChildByName("btn_ok");
        okBtn.getComponent(cc.Button).interactable = true;
        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale:1}, {easing:"backOut"})
                .start();
            let title = cc.find("theme171_free_more_you_win", panel);
            title.scale = 0;
            cc.tween(title)
                .delay(0.2)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();
            let label = cc.find("label", panel);
            label.scale = 0;
            cc.tween(label)
                .delay(0.2)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();
            let handler = ()=>{
                okBtn.off(cc.Node.EventType.TOUCH_END);
                okBtn.getComponent(cc.Button).interactable = false;
                SlotsFacade.soundMgr.playEffect("common_click");
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, ()=>{
                okBtn.stopAllActions();
                handler();
            });
        });
    },

    /**
     * 赢取jp金币奖励
     * @param {*} jpType jp类型 1~4-5 mini~grand-maxi
     * @param {*} goldNumb 
     */
    async showJpWinGold(jpType, goldNumb) {
        SlotsFacade.soundMgr.playEffect("jp_popup_in");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_jp_coin");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent("LabelRollCmp").startRoll(0, goldNumb);
        panel.getChildByName("bg").getComponent("ImgSwitchCmp").setIndex(jpType-1);
        // let logoSpine = panel.getChildByName("spine_logo").getComponent(sp.Skeleton);
        // logoSpine.setAnimation(0, "animation", false);
        let titleSpine = panel.getChildByName("spine_title").getComponent(sp.Skeleton);
        titleSpine.setAnimation(0, "animation" + [0, 5, 4, 3, 1, 2][jpType], true); //todo 确认jptype返回的值
        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale:1}, {easing:"backOut"})
                .start();
            cc.tween(panel)
                .delay(4)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.showBg(false);
                    panel.active = false;
                    SlotsFacade.soundMgr.playEffect("popup_out");
                    res();
                })
                .start();
        });
    },

    /**
     * 显示赢取免费次数
     * @param {number} cnt  
     * @param {*} cnt 
     * @param {*} isFirstTrigger 是否是首次触发
     */
    async showWinFreeCnt(cnt, isFirstTrigger) {
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_free_cnt");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent(cc.Label).string = cnt.toString();
        let okBtn = panel.getChildByName("btn_ok");
        okBtn.getComponent(cc.Button).interactable = true;
        okBtn.active = isFirstTrigger;
        // panel.getChildByName("btn_bg").active = isFirstTrigger;
        await new Promise(res=>{
            let tw = cc.tween(panel);
            tw = tw.to(0.5, {scale:1}, {easing:"backOut"});
            if(isFirstTrigger) {
                SlotsFacade.soundMgr.playEffect("free_dialog_start_show");
                let handler = ()=>{
                    SlotsFacade.soundMgr.playEffect("common_click");
                    okBtn.off(cc.Node.EventType.TOUCH_END);
                    okBtn.getComponent(cc.Button).interactable = false;
                    cc.tween(panel)
                        .to(0.5, {scale:0}, {easing:"backIn"})
                        .call(()=>{
                            this.showBg(false);
                            panel.active = false;
                            SlotsFacade.soundMgr.playEffect("popup_out");
                            res();
                        })
                        .start();
                };
                cc.vv.gameData.checkAutoPlay(okBtn, handler);
                okBtn.on(cc.Node.EventType.TOUCH_END, ()=>{
                    okBtn.stopAllActions();
                    handler();
                });
            }else {
                SlotsFacade.soundMgr.playEffect("free_dialog_more_show");
                tw = tw
                .delay(1)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.showBg(false);
                    panel.active = false;
                    res();
                });

                cc.find("label", panel).scale = 0;
                cc.tween(cc.find("label", panel))
                    .delay(0.2)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .start();
            }
            tw.start();
        });
    },
 })