cc.Class({
    extends:cc.Component,

    properties: {
        _lockItems:null,
        up:cc.Node,
        down:cc.Node,
        border:cc.Node,
        // shangsheng:sp.Skeleton,
        // shengqipan:sp.Skeleton,
    },

    onLoad() {
        this._lockItems = [];
        for(let i=0; i<4; i++) {
            let item = this.border.getChildByName("row" + (i+1)).getComponent("BladeMasterTokugawa_LockItem");
            this._lockItems.push(item);
        }
        this.border.y = -370;
    },

    reset() {
        this._lockItems.forEach(element => {
            element.reset();
        });
    },

    async show() {
        this.up.active = true;
        this.down.active = true;
        SlotsFacade.soundMgr.playEffect("reel_raise");
        this.border.y = -370;
        cc.tween(this.border)
            .delay(0.5)
            .to(1.5, {y:0})
            .start();
        // await new Promise(res=>{
        //     this.shengqipan.node.active = true;
        //     this.shengqipan.setAnimation(0, "animation", false);
        //     this.shengqipan.setCompleteListener(()=>{
        //         this.shengqipan.setCompleteListener(null);
        //         this.shengqipan.setAnimation(0, "animation2", false);
        //         res();
        //     });
        // });
        
        // this.shangsheng.node.active = true;
        // this.shangsheng.setAnimation(0, "animation", false);
        // this.shangsheng.setCompleteListener(()=>{
        //     this.shangsheng.setCompleteListener(null);
        //     this.shangsheng.node.active = false;
        // });

        let jk = SlotsFacade.dm.getJungleKing();
        for(let i=0; i<this._lockItems.length; i++) {
            let item = this._lockItems[i];
            item.show(jk.tierCfg[i] - jk.total);
            await SlotsFacade.delayTime(0.1*i);
        }
    },

    hide() {
        this.reset();
        this.up.active = false;
        this.down.active = false;
    },

    reconnect() {
        this.scheduleOnce(()=>{
            SlotsFacade.soundMgr.playFreeBgm();
            // this.shangsheng.node.active = false;
            this.up.active = true;
            this.down.active = true;
            this.border.y = 0;
            let jk = SlotsFacade.dm.getJungleKing();
            for(let i=0; i<this._lockItems.length; i++) {
                let item = this._lockItems[i];
                item.setNeedCnt(jk.tierCfg[i] - jk.total);
            }
        });
    },

    /**
     * 处理解锁逻辑
     */
    async processUnlock() {
        if(!SlotsFacade.dm.inFree()) {
            return;
        }
        let jk = SlotsFacade.dm.getJungleKing();
        let currCnt = jk.idxs.length;
        if(currCnt < 1) {
            return;
        }
        let unlocAllNeedCnt = jk.tierCfg[jk.tierCfg.length-1];
        let hasUnlock = jk.total - currCnt;
        if(unlocAllNeedCnt <= hasUnlock) {
            return;
        }

        for(let i=0; i<currCnt; i++) {
            let symbol = SlotsFacade.slots.GetSymbolByIdx(jk.idxs[i]);
            await symbol.showJKAni();
            let promiseArr = [];
            for(let i=0; i<this._lockItems.length; i++) {
                let item = this._lockItems[i];
                promiseArr.push(item.minusCnt());
            }
            SlotsFacade.soundMgr.playEffect("number_add");
            await Promise.all(promiseArr);
            hasUnlock++;
            if(unlocAllNeedCnt <= hasUnlock) {
                break;
            }
        }
    }
});