cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        canPlayWinMultiple:false, // 是否需要播放multiple win动画
        isSingle:false,     // 是否是单个wild
    },

    /**
     * @override
     */
    StartMove:function(){
        this._super()
        this.showMultiple();
    },

    /**
     * 显示金色头像动画
     */
    async showJKAni() {
        if(this._id != 4) {
            return;
        }
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true
            if(cfg.symbol[id].win_ani){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    await new Promise(res=>{
                        SlotsFacade.soundMgr.playEffect("sbonus_notify");
                        nodeSp.setAnimation(0,cfg.symbol[id].unlockAni, false)
                        nodeSp.setCompleteListener(()=>{
                            nodeSp.setCompleteListener(null);
                            res();
                        });
                    })
                }
            }
        }
    },

    /**
     * @override
     */
    playWinAnimation() {
        this._super();
        if(this.canPlayWinMultiple) {
            this.showMultiple(true, 2, this.isSingle);
        }
    },

    /**
     * 显示倍数
     * @param {*} visible  是否显示
     * @param {*} type 动画类型 1-出现 2-胜利 3-静止
     * @param {*} isSingle 是否是单个wild
     */
    showMultiple(visible, type, isSingle) {
        if(visible) {
            let id = this.GetShowId();
            if(![101, 102, 2101, 2102].includes(id)) {
                return;
            }
            this.isSingle = isSingle;
            let aniNode = this.setAnimationToTop(true);
            aniNode.active = true
            let spine = null;
            if(id == 101 || id == 2101) {
                spine = aniNode.getChildByName("multiple2").getComponent(sp.Skeleton);                
            }else {
                spine = aniNode.getChildByName("multiple3").getComponent(sp.Skeleton);
            }
            spine.node.active = true;
            if(isSingle) {
                spine.setAnimation(0, `animation2_${type}`, type == 2);
            }else {
                spine.setAnimation(0, `animation1_${type}`, type == 2);
            }
        }else {
            this.node.getChildByName("multiple2").active = false;
            this.node.getChildByName("multiple3").active = false;
            this.canPlayWinMultiple = false;
        }
    },

    /**
     * 播放jackport
     * @param {*} jpType 1~4-5 mini~grand-maxi
     * @param {*} isBig  是否占用2格的jackpot
     */
    async playJp(jpType, isBig) {
        if(this._showNode){
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true);
        aniNode.active = true;
        let topShowNode = cc.find("w_jp",aniNode);
        topShowNode.active = true
        // 显示对应背景动画
        let bgName = `bg${isBig?"2":""}_${jpType}`;
        let bgSpine = topShowNode.getChildByName(bgName).getComponent(sp.Skeleton);
        bgSpine.node.active = true;
        bgSpine.setAnimation(0, "animation", true);
        // 播放flash动画
        let flashName = `flash${isBig?"2":"1"}`;
        let flashSpine = topShowNode.getChildByName(flashName).getComponent(sp.Skeleton);
        flashSpine.node.active = true;
        await new Promise(res=>{
            flashSpine.setAnimation(0, "animation", false);
            flashSpine.setCompleteListener(()=>{
                flashSpine.setCompleteListener(null);
                flashSpine.node.active = false;
                res();
            });
        });
        // 播放jackport文字
        let labelName = `label${isBig?"2":""}_${jpType}`;
        let labelSpine = topShowNode.getChildByName(labelName).getComponent(sp.Skeleton);
        labelSpine.node.active = true;
        labelSpine.setAnimation(0, "animation", true);
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * jp转成wild
     */
    async jpToWild(isBig) {
        this.canPlayWinMultiple = true;
        this.setAnimationToTop(false)
        let aniNode = this.setAnimationToTop(true);
        aniNode.active = true;
        let topShowNode = cc.find("w_jp",aniNode);
        topShowNode.active = true
        // 播放flash动画
        let flashName = `flash${isBig?"2":"1"}`;
        let flashSpine = topShowNode.getChildByName(flashName).getComponent(sp.Skeleton);
        flashSpine.node.active = true;
        await new Promise(res=>{
            flashSpine.setAnimation(0, "animation", false);
            flashSpine.setCompleteListener(()=>{
                flashSpine.setCompleteListener(null);
                flashSpine.node.active = false;
                res();
            });
        });
        this.showMultiple(true, 1, !isBig);
    }
});
