cc.Class({
    extends:cc.Component,
    properties: {
        tenmanType:0,
        tenman:sp.Skeleton, //藤曼
        mask:cc.Node,
        label:cc.Label,
        labelEffect:sp.Skeleton,
        wenzi:sp.Skeleton,
        taishaniconguang:sp.Skeleton,
        cnt:0,
    },

    onLoad() {
        this.reset();
    },

    reset() {
        this.tenman.node.active = false;
        this.mask.active = true;
        this.label.node.active = false;
        this.labelEffect.node.active = false;
        this.wenzi.node.active = false;
        this.taishaniconguang.node.active = false;
        this.cnt = 0;
    },

    async show(cnt) {
        //this.node.active = true;
        this.mask.opacity = 0xff;
        this.reset();
        this.cnt = cnt;
        this.lock(cnt);
    },

    async hide() {
        await this.unlock();
        await new Promise(res=>{
            cc.tween(this.mask)
            .to(0.5, {opacity:0})
            .call(()=>{
                res();
            })
            .start();
        });
    },

    /**
     * 枷锁
     */
    async lock(cnt) {
        this.label.string = cnt.toString();
        await new Promise(res=>{
            cc.tween(this.node)
            .call(()=>{
                //播放藤曼动画
                SlotsFacade.soundMgr.playEffect("vine1");
                this.tenman.node.active = true;
                this.tenman.setAnimation(0, ["animation1", "animation2"][this.tenmanType], false);
                this.tenman.setCompleteListener(()=>{
                    this.tenman.setCompleteListener(null);
                    this.tenman.setAnimation(0, ["animation3", "animation4"][this.tenmanType], true);
                });
            })
            .delay(0.7)
            .call(()=>{
                // 播放文字
                SlotsFacade.soundMgr.playEffect("number_appear");
                this.labelEffect.node.active = true;
                this.labelEffect.setAnimation(0, "animation", false);
                this.labelEffect.setCompleteListener(()=>{
                    this.labelEffect.setCompleteListener(null);
                    this.labelEffect.node.active = false;
                });
            })
            .delay(0.5)
            .call(()=>{
                // 显示文字
                this.label.node.active = true;
                this.wenzi.node.active = true;
                this.wenzi.setAnimation(0, "animation1", false);
                this.wenzi.setCompleteListener(()=>{
                    this.wenzi.setCompleteListener(null);
                    this.wenzi.setAnimation(0, "animation3", true);
                });
            })
            .delay(0.5)
            .call(()=>{
                res();
            })
            .start();
        });
    },
    
    /**
     * 解锁
     */
    async unlock() {
        await SlotsFacade.delayTime(0.5);
        this.labelEffect.node.active = true;
        this.labelEffect.setAnimation(0, "animation", false);
        this.labelEffect.setCompleteListener(()=>{
            this.labelEffect.node.active = false;
        });
        this.label.node.active = false;
        this.wenzi.node.active = false;
        SlotsFacade.soundMgr.playEffect("vine2");
        await new Promise(res=>{
            this.tenman.node.active = true;
            this.tenman.setAnimation(0, ["animation1_1", "animation2_1"][this.tenmanType], false);
            this.tenman.setCompleteListener(()=>{
                this.tenman.node.active = false;
                res();
            });
        });
    },

    /**
     * 设置解锁需要的头像数量
     * @param {*} cnt 数量
     * @param {*} ani 是否需要展示动画
     */
    setNeedCnt(cnt, ani) {
        if(cnt>0) {
            this.cnt = cnt;
            this.label.node.active = true;
            this.label.string = cnt.toString();
            this.wenzi.node.active = true;
            this.wenzi.setAnimation(0, "animation3", true);
            this.tenman.node.active = true;
            this.tenman.setAnimation(0, ["animation3", "animation4"][this.tenmanType], true);
        } else {
            this.node.active = false;
        }
    },

    async minusCnt() {
        if(this.cnt < 1) {
            return;
        }
        if(this.cnt == 1) {
            this.cnt --;
            await this.hide();
        }else {
            this.cnt --;
            this.label.string = this.cnt.toString();
            this.labelEffect.node.active = true;
            this.labelEffect.setAnimation(0, "animation", false);
            this.labelEffect.setCompleteListener(()=>{
                this.labelEffect.setCompleteListener(null);
                this.labelEffect.node.active = false;
            });
            this.taishaniconguang.node.active = true;
            this.taishaniconguang.setAnimation(0, "animation", false);
            this.taishaniconguang.setCompleteListener(()=>{
                this.taishaniconguang.setCompleteListener(null);
                this.taishaniconguang.node.active = false;
            });
            SlotsFacade.delayTime(0.5);
        }
    }
})