/**
 * 判断id 是否为wild
 * @param {number} id 
 */
Cfg.isWild = function(id) {
    return id == 1 || id == 101 ||  id == 102 || id == 2001 ||  id == 2101 ||  id == 2102;
};

Cfg.isMultipleWild = function(id) {
    return id == 101 ||  id == 2101 || id == 102 || id == 2102;
};

