cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        bg:cc.Node, //背景
    },

    /**
     * @override
     * @param {*} idx 
     * @param {*} nCount 
     */
    Init:function(idx,nCount, node){
        this._super(idx,nCount, node);
        this.bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent);
    },

    /**
     * @override
     */
    ShowAntiEffect:function(bShow,name){
        this._super(bShow,name);
        if(bShow) {
            let node = cc.find("mask/" + name,this.node)
            if(node){
                node.active = bShow;
                let spine = node.getComponent(sp.Skeleton);
                spine.setAnimation(0, "animation1", false);
            }
        }
    },

    /**
     * 改变卷轴背景
     * @param {*} isSpecial 是否是特殊背景
     */
    changeReelBg(isSpecial) {
        let cmp = this.bg.getComponent("ImgSwitchCmp");
        if(!cmp) {
            return;
        }
        if(isSpecial) {
            cmp.setIndex(1);
        }else {
            cmp.setIndex(0);
        }
    },

    /**
     * @override
     */
    playReelStop(){
        this._super();
        for(let i = 0; i < this._symbols.length; i++){
            let item = this._symbols[i]
            for (let info of this._reelState) {
                if (info.isStop && info.id.includes(item.GetShowId())) {
                    this.changeReelBg(true);
                    return;
                }
            } 
        }
    },
})